+#include <fenv.h>
+
+static void
+test_cfl_zero_transition(void)
+{
+  gkyl_gyrokinetic_app *app = new_app(false, GKYL_GK_COLLISIONLESS_ES, false);
+  struct gk_species *species = &app->species[0];
+  struct gkyl_gyrokinetic_collisionless inp = collisionless_input(GKYL_GK_COLLISIONLESS_ES, true);
+  inp.time_rate_multiplier.num_multipliers = 2;
+  inp.time_rate_multiplier.multiplier[0].time_dilation_scale_const = 0.37;
+  inp.time_rate_multiplier.multiplier[1] = (struct gkyl_gyrokinetic_fdot_multiplier_comp){
+    .type = GKYL_GK_FDOT_MULTIPLIER_CONSTANT,
+    .cellwise_const = true,
+    .time_dilation_scale_const = 0.5,
+  };
+  gkyl_gyrokinetic_app_reset_species_collisionless(app, 0.0, "ion", inp);
+
+  const double rates[] = {0.0, 0.001, 0.02, 0.2, 0.4};
+  struct gkyl_array *unscaled = gkyl_array_new(GKYL_DOUBLE, 1, species->cflrate->size);
+  for (int phase = 0; phase < 3; ++phase) {
+    // An enabled operator can go from zero to finite CFL and back to zero.
+    // Populate only interior cells, so every ghost cell retains a zero CFL.
+    gkyl_array_clear(species->cflrate, 0.0);
+    if (phase == 1) {
+      struct gkyl_range_iter iter;
+      gkyl_range_iter_init(&iter, &species->local);
+      while (gkyl_range_iter_next(&iter)) {
+        long loc = gkyl_range_idx(&species->local, iter.idx);
+        ((double *)gkyl_array_fetch(species->cflrate, loc))[0] = rates[loc % 5];
+      }
+    }
+    gkyl_array_copy(unscaled, species->cflrate);
+    gkyl_array_clear(species->f1, 2.0);
+    feclearexcept(FE_ALL_EXCEPT);
+    gk_species_fdot_multiplier_advance_times_cfl(
+      app, species, &species->collisionless.fdot_mult, app->field->phi_smooth,
+      species->f, species->cflrate
+    );
+    gk_species_fdot_multiplier_advance_times_rate(
+      app, species, &species->collisionless.fdot_mult, app->field->phi_smooth,
+      species->f, species->f1
+    );
+    TEST_CHECK(fetestexcept(FE_INVALID) == 0);
+    for (size_t loc = 0; loc < species->cflrate->size; ++loc) {
+      double rate = ((const double *)gkyl_array_cfetch(unscaled, loc))[0];
+      double expected_mult = 0.37 * 0.5;
+      if (rate > 0.04) {
+        expected_mult *= 0.04 / rate;
+      }
+      double mult = ((const double *)gkyl_array_cfetch(
+        species->collisionless.fdot_mult.multiplier, loc
+      ))[0];
+      double cfl = ((const double *)gkyl_array_cfetch(species->cflrate, loc))[0];
+      const double *rhs = gkyl_array_cfetch(species->f1, loc);
+      TEST_CHECK(isfinite(mult) && fabs(mult - expected_mult) < 1e-14);
+      TEST_CHECK(isfinite(cfl) && fabs(cfl - rate * expected_mult) < 1e-14);
+      for (int k = 0; k < species->basis.num_basis; ++k) {
+        TEST_CHECK(isfinite(rhs[k]) && fabs(rhs[k] - 2.0 * expected_mult) < 1e-14);
+      }
+    }
+  }
+  gkyl_array_release(unscaled);
+  gkyl_gyrokinetic_app_release(app);
+}
*** End Patch"));
